import{c as t,Q as a,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"GPT-5.4 Thinking System Card","description":"","frontmatter":{"url":"https://deploymentsafety.openai.com/gpt-5-4-thinking/gpt-5-4-thinking.pdf","title":"GPT-5.4 Thinking System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["OpenAI"],"domains":["system-card"],"pdf_path":"pdfs/openai-gpt-5-4-thinking-system-card.pdf","published_date":"2026-03-05T00:00:00.000Z","source_url":"https://deploymentsafety.openai.com/gpt-5-4-thinking/gpt-5-4-thinking.pdf"},"headers":[],"relativePath":"research/papers/2026-03-05-openai-gpt-5-4-thinking-system-card.md","filePath":"research/papers/2026-03-05-openai-gpt-5-4-thinking-system-card.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-03-05-openai-gpt-5-4-thinking-system-card.md"};function o(s,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="gpt-5-4-thinking-system-card" tabindex="-1">GPT-5.4 Thinking System Card <a class="header-anchor" href="#gpt-5-4-thinking-system-card" aria-label="Permalink to &quot;GPT-5.4 Thinking System Card&quot;">​</a></h1><p><strong>Source</strong>: <a href="https://deploymentsafety.openai.com/gpt-5-4-thinking/gpt-5-4-thinking.pdf" target="_blank" rel="noreferrer">https://deploymentsafety.openai.com/gpt-5-4-thinking/gpt-5-4-thinking.pdf</a><strong>Published</strong>: March 05, 2026 <strong>PDF</strong>: <code>research/papers/pdfs/openai-gpt-5-4-thinking-system-card.pdf</code> (38 pp, full text archived)</p><hr><h2 id="摘要-依官方-pdf-結構與公開資訊整理" tabindex="-1">摘要（依官方 PDF 結構與公開資訊整理） <a class="header-anchor" href="#摘要-依官方-pdf-結構與公開資訊整理" aria-label="Permalink to &quot;摘要（依官方 PDF 結構與公開資訊整理）&quot;">​</a></h2><ul><li>GPT-5.4 Thinking 為 OpenAI 推理（thinking）系列模型的 system card，涵蓋模型資料與訓練、baseline 安全評估、chain-of-thought 評估，以及 Preparedness Framework 能力評估。</li><li>System card 章節結構（取自 PDF 大綱）：§1 Introduction、§2 Model Data and Training、§3 Baseline Model Safety Evaluations（含 Disallowed Content、Production Benchmarks、Jailbreaks、Prompt injection、Vision、Health、Avoid Accidental Data-Destructive Actions、User Confirmations During Computer Use、Bias）、§4 Chain of Thought Evaluations（CoT Monitorability、CoT Controllability）、§5 Preparedness Framework（Capabilities Assessment：Biological and Chemical、Cybersecurity、AI Self-Improvement）。</li></ul><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li>推理（thinking）導向旗艦模型；延續 o-series/GPT-5 系列以 chain of thought 推理為核心。</li><li>安全評估特別納入 agentic/computer-use 面向：避免意外的 data-destructive 動作、computer use 期間的 user confirmation。</li></ul><h3 id="關鍵能力-安全評估數字" tabindex="-1">關鍵能力 / 安全評估數字 <a class="header-anchor" href="#關鍵能力-安全評估數字" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字&quot;">​</a></h3><ul><li>Baseline 安全：Disallowed content（challenging prompts）、production benchmarks、jailbreaks、prompt injection、vision、health、bias 等多面向評估。</li><li>Chain of Thought：評估 CoT Monitorability 與 CoT Controllability（推理鏈可監控/可控性）。</li><li>Preparedness Framework 三 Tracked Categories：<strong>Biological and Chemical、Cybersecurity、AI Self-Improvement</strong>（含 ProtocolQA、TroubleshootingBench、CTF、CVE-Bench、Cyber range、MLE-Bench、Monorepo-Bench 等子評測）。</li><li>具體風險等級與數字以 PDF 全文為準（本檔依官方 PDF 大綱整理）。</li></ul><h3 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h3><ul><li>「Avoid Accidental Data-Destructive Actions」與「User Confirmations During Computer Use」與 core.md APPLY「不可逆例外」鐵律高度一致——皆要求對破壞性/不可逆動作強制人為確認。</li><li>CoT Monitorability/Controllability 對應本庫「judgement vs decision」與 unverified_success 閘門：推理過程須可觀測、可驗證，不以模型自評為證據。</li><li>Preparedness 的 AI Self-Improvement 類別呼應 core.md「harness 自我改進需 APPLY 前置 gate」。⚠️ 依官方公開資訊整理；風險等級數字以 PDF 全文為準。</li></ul>',13)])])}const g=t(r,[["render",o]]);export{m as __pageData,g as default};
